import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';

const root = process.argv[2];
const fail = [];

const home = readFileSync(join(root, 'src/pages/Home.jsx'), 'utf8');
const en = JSON.parse(readFileSync(join(root, 'src/i18n/en.json'), 'utf8'));

// exact resolver copy from src/i18n/index.js
const t = (key) => key.split('.').reduce((acc, part) => (acc || {})[part], en) || key;

// 1. the copy the homepage button actually renders
const buttonKey = home.match(/<button[^>]*>\s*\{t\('([^']+)'\)\}/s)?.[1];
console.log('homepage <button> i18n key:', buttonKey);
if (!buttonKey) fail.push('could not find an i18n key inside the homepage <button>');
else {
  const label = t(buttonKey);
  const resolved = label !== buttonKey;
  console.log(`  ${buttonKey} -> ${JSON.stringify(label)} ${resolved ? '(resolved)' : '(MISSING KEY)'}`);
  if (!resolved) fail.push(`${buttonKey} does not resolve`);
  if (label !== 'Create order') fail.push(`button renders ${JSON.stringify(label)}, expected "Create order"`);
}

// 2. the removed key is not referenced anywhere in src
const walk = (dir) => readdirSync(dir).flatMap((n) => {
  const p = join(dir, n);
  return statSync(p).isDirectory() ? walk(p) : [p];
});
for (const file of walk(join(root, 'src'))) {
  if (file.endsWith('.json')) continue;
  const body = readFileSync(file, 'utf8');
  if (body.includes('home.submit')) fail.push(`dangling reference to home.submit in ${file}`);
}
console.log('dangling home.submit references: none');

// 3. the homepage still has no hardcoded copy
if (/>\s*(Submit|Create order)\s*</.test(home)) fail.push('homepage button has hardcoded copy');

console.log(fail.length ? `FAIL\n- ${fail.join('\n- ')}` : 'PASS');
process.exit(fail.length ? 1 : 0);

